CREATE OR REPLACE FUNCTION public.expense_manual_booked(t uuid,a uuid,m date,amt numeric) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM journal_entries e JOIN journal_lines l ON l.entry_id=e.id WHERE e.tenant_id=t AND e.status='posted' AND e.source_type='manual' AND e.entry_date>=date_trunc('month',m)::date AND e.entry_date<date_trunc('month',m)+interval '1 month' AND l.account_id=a GROUP BY e.id HAVING abs(sum(l.debit-l.credit)-amt)<.01) $$;
REVOKE ALL ON FUNCTION public.expense_manual_booked(uuid,uuid,date,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.expense_manual_booked(uuid,uuid,date,numeric) TO authenticated,service_role;
DO $$ DECLARE def text; BEGIN
SELECT pg_get_functiondef('public.expense_monthend_run(uuid,date)'::regprocedure) INTO def;
def:=replace(def,'PERFORM public.expense_prepaid_release(line.id);posted:=posted+1;','n:=n+1;');
def:=replace(def,'IF r.auto_approve THEN','IF true THEN');
def:=replace(def,'IF r.auto_approve AND EXISTS(SELECT 1 FROM public.expense_accrual_drafts WHERE id=d AND status=''waiting'') THEN PERFORM public.expense_accrual_approve(d);posted:=posted+1;END IF;','');
def:=replace(def,'IF EXISTS(SELECT 1 FROM public.expense_accrual_drafts WHERE id=d AND status=''waiting'') THEN PERFORM public.expense_accrual_approve(d);posted:=posted+1;END IF;','');
def:=replace(def,'amt:=public.expense_contract_month_amount(r.id,m);','amt:=public.expense_contract_month_amount(r.id,m); IF public.expense_manual_booked(t,r.account_id,m,amt) THEN CONTINUE;END IF;');
IF def LIKE '%PERFORM public.expense_accrual_approve%' OR def LIKE '%PERFORM public.expense_prepaid_release%' OR def LIKE '%PERFORM public.post_prepaid_line%' THEN RAISE EXCEPTION 'Draft-only replacement failed'; END IF;EXECUTE def;
SELECT pg_get_functiondef('public.expense_accrual_approve(uuid)'::regprocedure) INTO def;
def:=replace(def,'IF d.status=''posted'' THEN','IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),''admin'') OR EXISTS(SELECT 1 FROM tenant_members tm WHERE tm.tenant_id=d.tenant_id AND tm.user_id=auth.uid() AND tm.position=''owner'')) THEN RAISE EXCEPTION ''Owner or admin approval required'';END IF; PERFORM pg_advisory_xact_lock(hashtextextended(''expense-month:''||d.tenant_id::text||d.month_start::text,0)); IF public.expense_manual_booked(d.tenant_id,d.account_id,d.month_start,d.amount) THEN RAISE EXCEPTION ''Booked by hand; duplicate posting blocked'';END IF; IF d.status=''posted'' THEN');EXECUTE def;
SELECT pg_get_functiondef('public.expense_contract_bill_approve(uuid)'::regprocedure) INTO def;
def:=replace(def,'INSERT INTO public.expense_accrual_drafts','IF public.expense_manual_booked(b.tenant_id,r.account_id,m,public.expense_contract_month_amount(r.id,m)) THEN RAISE EXCEPTION ''Booked by hand; duplicate posting blocked'';END IF; INSERT INTO public.expense_accrual_drafts');EXECUTE def;
SELECT pg_get_functiondef('public.bani_accounting_commit(uuid,uuid,text,text,text,uuid)'::regprocedure) INTO def;
def:=replace(def,'IF r.status=''posted'' THEN','IF r.source_type=''expense_bill'' THEN RAISE EXCEPTION ''Expenses require explicit approval'';END IF; IF r.status=''posted'' THEN');EXECUTE def;
END $$;
CREATE OR REPLACE FUNCTION public.expense_month_approve(t uuid,m date,p_items jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb;ident uuid;n int:=0;b expense_bills%ROWTYPE;BEGIN
IF auth.uid() IS NULL OR NOT public.user_has_tenant(auth.uid(),t) OR NOT(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM tenant_members tm WHERE tm.tenant_id=t AND tm.user_id=auth.uid() AND tm.position='owner')) THEN RAISE EXCEPTION 'Owner or admin approval required';END IF;
m:=date_trunc('month',m)::date; IF jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 OR jsonb_array_length(p_items)>200 THEN RAISE EXCEPTION 'Select drafts to approve';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('expense-month:'||t::text||m::text,0));
FOR item IN SELECT * FROM jsonb_array_elements(p_items) LOOP ident:=(item->>'id')::uuid;
IF item->>'kind'='accrual' THEN IF NOT EXISTS(SELECT 1 FROM expense_accrual_drafts WHERE id=ident AND tenant_id=t AND month_start=m AND status='waiting') THEN RAISE EXCEPTION 'Monthly draft changed';END IF; PERFORM expense_accrual_approve(ident);
ELSIF item->>'kind'='prepaid' THEN IF NOT EXISTS(SELECT 1 FROM prepaid_schedule_lines WHERE id=ident AND tenant_id=t AND period=m AND status='pending') THEN RAISE EXCEPTION 'Release draft changed';END IF;PERFORM expense_prepaid_release(ident);
ELSIF item->>'kind'='bill' THEN SELECT * INTO b FROM expense_bills WHERE id=ident AND tenant_id=t AND approval_status IN ('draft','pending_review','approved') FOR UPDATE; IF NOT FOUND OR date_trunc('month',coalesce(b.service_period_start,b.period_start,b.bill_date))::date<>m THEN RAISE EXCEPTION 'Monthly bill changed';END IF; IF b.source_type='recurring_rule' AND EXISTS(SELECT 1 FROM expense_recurring_rules WHERE id=b.recurring_rule_id AND is_contract) THEN PERFORM expense_contract_bill_approve(ident);ELSE PERFORM approve_and_post_expense_bill(ident);END IF;
ELSE RAISE EXCEPTION 'Unknown monthly draft';END IF;n:=n+1;END LOOP;RETURN jsonb_build_object('posted',n);END $$;
REVOKE ALL ON FUNCTION public.expense_month_approve(uuid,date,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.expense_month_approve(uuid,date,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.expense_manual_bill_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r expense_recurring_rules%ROWTYPE;m date;BEGIN IF NEW.approval_status='posted' AND OLD.approval_status IS DISTINCT FROM 'posted' AND NEW.recurring_rule_id IS NOT NULL THEN SELECT * INTO r FROM expense_recurring_rules WHERE id=NEW.recurring_rule_id AND tenant_id=NEW.tenant_id;m:=date_trunc('month',coalesce(NEW.service_period_start,NEW.period_start,NEW.bill_date))::date;IF r.is_contract AND expense_manual_booked(NEW.tenant_id,r.account_id,m,expense_contract_month_amount(r.id,m)) THEN RAISE EXCEPTION 'Booked by hand; duplicate posting blocked';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER expense_manual_bill_guard BEFORE UPDATE OF approval_status ON expense_bills FOR EACH ROW EXECUTE FUNCTION expense_manual_bill_guard();
COMMENT ON COLUMN expense_recurring_rules.auto_approve IS 'DEPRECATED: Expenses require explicit approval; legacy values ignored.';